// Load Credentials v5 — v4 architecture + v3 full personalization
const prev = $('Extract Payload').first().json;
const p = prev.persona || {};
const t = p.tokens || {};
const lang = p.language_preference || 'th';

// ── i18n: v3 full keys restored ───────────────────────────────
const i18nMap = {
  th: {
    not_connected:  'ยังไม่ได้เชื่อมต่อ',
    configure:      'กรุณาตั้งค่าที่ /dashboard/api-settings',
    success:        'สำเร็จ',
    error:          'เกิดข้อผิดพลาด',
    completed:      'เสร็จแล้ว',
    query_required: 'กรุณาระบุคำค้นหา',
    room_required:  'กรุณาระบุชื่อห้อง',
    name_required:  'กรุณาระบุชื่อ',
    youtube_note:   'YouTube Music ต้องเปิดใน app/browser ครับ',
    sonos_note:     'กรุณาตรวจสอบว่า node-sonos-http-api ทำงานอยู่'
  },
  en: {
    not_connected:  'Not connected',
    configure:      'Please configure at /dashboard/api-settings',
    success:        'Success',
    error:          'Error occurred',
    completed:      'Completed',
    query_required: 'query is required',
    room_required:  'room name is required',
    name_required:  'name is required',
    youtube_note:   'YouTube Music must be opened in app/browser',
    sonos_note:     'Please check that node-sonos-http-api is running'
  },
  ja: {
    not_connected:  '接続されていません',
    configure:      '/dashboard/api-settingsで設定してください',
    success:        '成功しました',
    error:          'エラーが発生しました',
    completed:      '完了しました',
    query_required: '検索クエリが必要です',
    room_required:  'ルーム名が必要です',
    name_required:  '名前が必要です',
    youtube_note:   'YouTube Musicはアプリ/ブラウザで開いてください',
    sonos_note:     'node-sonos-http-apiが起動しているか確認してください'
  },
  zh: {
    not_connected:  '未连接',
    configure:      '请在 /dashboard/api-settings 配置',
    success:        '成功',
    error:          '发生错误',
    completed:      '已完成',
    query_required: '需要搜索关键词',
    room_required:  '需要房间名称',
    name_required:  '需要名称',
    youtube_note:   'YouTube Music 需要在应用/浏览器中打开',
    sonos_note:     '请检查 node-sonos-http-api 是否正在运行'
  }
};
const i18n = i18nMap[lang] || i18nMap['en'];

const get = (envKey, payloadKey) => t[payloadKey] || p[payloadKey] || process.env[envKey] || '';

// ── Credentials: v3 full list + v4 additions ──────────────────
const creds = {
  google_access_token:    get('GOOGLE_ACCESS_TOKEN',    'google_access_token'),
  google_refresh_token:   get('GOOGLE_REFRESH_TOKEN',   'google_refresh_token'),
  microsoft_access_token: get('MICROSOFT_ACCESS_TOKEN', 'microsoft_access_token'),
  outlook_access_token:   get('MICROSOFT_ACCESS_TOKEN', 'microsoft_access_token'),
  telegram_bot_token:     get('TELEGRAM_BOT_TOKEN',     'telegram_bot_token'),
  discord_bot_token:      get('DISCORD_BOT_TOKEN',      'discord_bot_token'),
  slack_bot_token:        get('SLACK_BOT_TOKEN',        'slack_bot_token'),
  twitter_bearer_token:   get('TWITTER_BEARER_TOKEN',   'twitter_bearer_token'),
  facebook_access_token:  get('FACEBOOK_ACCESS_TOKEN',  'facebook_access_token'),
  linkedin_access_token:  get('LINKEDIN_ACCESS_TOKEN',  'linkedin_access_token'),
  spotify_access_token:   get('SPOTIFY_ACCESS_TOKEN',   'spotify_access_token'),
  youtube_api_key:        get('YOUTUBE_API_KEY',        'youtube_api_key'),
  line_notify_token:      get('LINE_NOTIFY_TOKEN',      'line_notify_token'),
  google_maps_key:        get('GOOGLE_MAPS_API_KEY',    'google_maps_key'),
  brave_api_key:          get('BRAVE_API_KEY',          'brave_api_key'),
  openweathermap_key:     get('OPENWEATHERMAP_API_KEY', 'openweathermap_key'),
  fal_api_key:            get('FAL_API_KEY',            'fal_api_key'),
  elevenlabs_api_key:     get('ELEVENLABS_API_KEY',     'elevenlabs_api_key'),
  elevenlabs_voice_id:    get('ELEVENLABS_VOICE_ID',    'elevenlabs_voice_id') || 'pNInz6obpgDQGcFmaJgB',
  unsplash_access_key:    get('UNSPLASH_ACCESS_KEY',    'unsplash_access_key'),
  nutritionix_app_id:     get('NUTRITIONIX_APP_ID',     'nutritionix_app_id'),
  nutritionix_api_key:    get('NUTRITIONIX_API_KEY',    'nutritionix_api_key'),
  finnhub_api_key:        get('FINNHUB_API_KEY',        'finnhub_api_key'),
  // Home Assistant — support both v3 aliases (ha_url/ha_token) and v4 names
  ha_url:                 get('HOME_ASSISTANT_URL',     'ha_url') || get('HOME_ASSISTANT_URL', 'home_assistant_url'),
  ha_token:               get('HOME_ASSISTANT_TOKEN',   'ha_token') || get('HOME_ASSISTANT_TOKEN', 'home_assistant_token'),
  // Sonos — support both v3 (sonos_api_url) and v4 (sonos_controller_url)
  sonos_api_url:          get('SONOS_HTTP_API_URL',     'sonos_api_url') || get('SONOS_CONTROLLER_URL', 'sonos_controller_url'),
  // Last.fm — v3 full set
  lastfm_api_key:         get('LASTFM_API_KEY',         'lastfm_api_key'),
  lastfm_username:        get('LASTFM_USERNAME',        'lastfm_username'),
  lastfm_session_key:     get('LASTFM_SESSION_KEY',     'lastfm_session_key'),
  // Auth + infra
  internal_auth_token:    get('INTERNAL_AUTH_TOKEN',    'internal_auth_token'),
  n8n_base_url:           get('N8N_BASE_URL',           'n8n_base_url'),
  database_url:           prev.databaseUrl || get('DATABASE_URL', 'database_url'),
  github_token:           get('GITHUB_TOKEN',           'github_token'),
};

// ── OpenRouter keys for LLM fallback (v4) ────────────────────
const userOrKey  = t.openrouter_access_token || '';
const sysOrKey   = process.env.OPENROUTER_API_KEY || '';
const PAID_MODEL = 'anthropic/claude-haiku-4-5';
const FREE_MODEL = 'meta-llama/llama-3.3-70b-instruct:free';

// ── Build USER_CONTEXT (v3 depth restored) ────────────────────
const userContextParts = [];

if (p.name) userContextParts.push(`Name: ${p.name}`);
if (p.interests?.length > 0) userContextParts.push(`Interests: ${p.interests.join(', ')}`);
if (p.personality_notes) userContextParts.push(`Personality: ${p.personality_notes}`);
if (p.key_facts?.length > 0) {
  userContextParts.push(`Key Facts:\n${p.key_facts.map(f => `  - ${f}`).join('\n')}`);
}
if (p.physical_stats && Object.keys(p.physical_stats).length > 0) {
  const stats = Object.entries(p.physical_stats).map(([k,v]) => `${k}: ${v}`).join(', ');
  userContextParts.push(`Physical Stats: ${stats}`);
}
if (p.ethical_profile) {
  const ep = p.ethical_profile;
  userContextParts.push(
    `Growth Stage: ${ep.growth_stage} (${ep.growth_stage_label})` +
    (ep.top_strengths?.length > 0 ? ` | Strengths: ${ep.top_strengths.join(', ')}` : '')
  );
}
if (p.relevant_memories?.length > 0) {
  const memStr = p.relevant_memories.map(m => `  [${m.type}]: ${m.summary}`).join('\n');
  userContextParts.push(`Recent Memories (static snapshot):\n${memStr}`);
}

const USER_CONTEXT = userContextParts.length > 0
  ? `\n\n## WHAT I KNOW ABOUT YOU:\n${userContextParts.join('\n')}\n`
  : '';

// ── Growth Stage Behavior Guide (restored from v3 pattern) ────
const stage = p.ethical_profile?.growth_stage || 2;
const GROWTH_GUIDANCE = {
  1: 'User is a beginner — use simple language, be very supportive, patient',
  2: 'User is developing — encourage, guide step by step',
  3: 'User is growing — challenge with open questions, stimulate thinking',
  4: 'User is advanced — engage deeply, give space to explore',
  5: 'User is mature — be a thinking partner, minimal guidance needed'
}[stage] || '';

const connected = Object.entries(creds).filter(([k,v]) => v).map(([k]) => k);

console.log('[Load Credentials v5 HomeMate]', {
  userId: prev.userId?.substring(0,8)+'...',
  connected: connected.length,
  lang,
  hasUserKey: !!userOrKey,
  hasHA: !!(creds.ha_url && creds.ha_token),
  hasSonos: !!creds.sonos_api_url,
  hasSpotify: !!creds.spotify_access_token,
  growthStage: stage
});

return {
  json: {
    ...prev,
    credentials: creds,
    lang, i18n,
    USER_CONTEXT,
    GROWTH_GUIDANCE,
    stage,
    userOrKey, sysOrKey,
    PAID_MODEL, FREE_MODEL,
    _connected: connected,
    _persona: p
  }
};

const input = JSON.parse($input.first().json.query || '{}');
const query = input.query || input.q || '';
const limit = input.limit || 3;
const ctx    = $('Load Credentials').first().json;
const creds  = ctx.credentials || {};
const i18n   = ctx.i18n || {};
const userId = ctx.userId;
const dbUrl  = creds.database_url || process.env.DATABASE_URL || '';
const persona = ctx._persona || ctx.persona || {};
const tokens  = persona.tokens || {};
const embedKey = tokens.openrouter_access_token || process.env.OPENROUTER_API_KEY || '';

if (!dbUrl)   return { json: { error: `Database ${i18n.not_connected||'not connected'}`, memories: [] } };
if (!query || query.length < 3) return { json: { error: 'Query too short (min 3 chars)', memories: [] } };
if (!embedKey) return { json: { error: 'OpenRouter key not configured', memories: [] } };

try {
  const embedRes = await fetch('https://openrouter.ai/api/v1/embeddings', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${embedKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ model: 'openai/text-embedding-3-small', input: query })
  });
  if (!embedRes.ok) {
    const err = await embedRes.text();
    return { json: { error: `OpenRouter embed failed: ${embedRes.status} ${err}`, memories: [] } };
  }
  const embedData = await embedRes.json();
  const embedding = embedData.data?.[0]?.embedding;
  if (!embedding || !Array.isArray(embedding)) return { json: { error: 'No embedding returned', memories: [] } };

  const { Pool } = require('pg');
  const pool = new Pool({ connectionString: dbUrl });
  const vectorStr = `[${embedding.join(',')}]`;
  const result = await pool.query(
    `SELECT content, metadata, created_at,
            1 - (embedding <=> $1::vector) AS similarity
     FROM user_data_schema.memory_embeddings
     WHERE user_id = $2
       AND embedding IS NOT NULL
       AND 1 - (embedding <=> $1::vector) > 0.6
     ORDER BY embedding <=> $1::vector
     LIMIT $3`,
    [vectorStr, userId, limit]
  );
  await pool.end();
  const memories = result.rows.map(r => ({
    content: r.content,
    similarity: parseFloat(r.similarity.toFixed(3)),
    metadata: r.metadata || {},
    date: new Date(r.created_at).toLocaleDateString('th-TH')
  }));
  if (memories.length === 0) return { json: { message: 'No relevant memories found', memories: [], query } };
  return { json: { memories, count: memories.length, query } };
} catch(err) {
  return { json: { error: `${i18n.error||'Error'}: ${err.message}`, memories: [] } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n = ctx.i18n || {};
const action = (input.action || 'now_playing').toLowerCase();
const token = creds.spotify_access_token || '';

if (!token) return { json: { error: `Spotify ${i18n.not_connected}`, help: i18n.configure } };
const headers = { 'Authorization': `Bearer ${token}`, 'Content-Type': 'application/json' };

try {
  if (action === 'now_playing') {
    const res = await fetch('https://api.spotify.com/v1/me/player', { headers });
    if (res.status === 204) return { json: { status: 'nothing playing' } };
    const d = await res.json();
    return { json: { is_playing: d.is_playing, track: d.item?.name, artist: d.item?.artists?.[0]?.name, album: d.item?.album?.name, progress_ms: d.progress_ms, duration_ms: d.item?.duration_ms, device: d.device?.name } };
  }
  if (action === 'pause') {
    await fetch('https://api.spotify.com/v1/me/player/pause', { method: 'PUT', headers });
    return { json: { success: true, message: i18n.success, action: 'paused' } };
  }
  if (action === 'resume' || (action === 'play' && !input.query && !input.uri)) {
    await fetch('https://api.spotify.com/v1/me/player/play', { method: 'PUT', headers });
    return { json: { success: true, message: i18n.success, action: 'resumed' } };
  }
  if (action === 'next') {
    await fetch('https://api.spotify.com/v1/me/player/next', { method: 'POST', headers });
    return { json: { success: true, message: i18n.success, action: 'next track' } };
  }
  if (action === 'prev') {
    await fetch('https://api.spotify.com/v1/me/player/previous', { method: 'POST', headers });
    return { json: { success: true, message: i18n.success, action: 'previous track' } };
  }
  if (action === 'set_volume') {
    const vol = Math.min(100, Math.max(0, parseInt(input.volume_pct || 50)));
    await fetch(`https://api.spotify.com/v1/me/player/volume?volume_percent=${vol}`, { method: 'PUT', headers });
    return { json: { success: true, message: i18n.success, volume_pct: vol } };
  }
  if (action === 'set_shuffle') {
    await fetch(`https://api.spotify.com/v1/me/player/shuffle?state=${input.enabled !== false}`, { method: 'PUT', headers });
    return { json: { success: true, message: i18n.success, shuffle: input.enabled !== false } };
  }
  if (action === 'search') {
    if (!input.query) return { json: { error: i18n.query_required || 'query required for search' } };
    const type = input.type || 'track,playlist,artist';
    const res = await fetch(`https://api.spotify.com/v1/search?q=${encodeURIComponent(input.query)}&type=${type}&limit=5&market=TH`, { headers });
    const d = await res.json();
    const results = {};
    if (d.tracks)    results.tracks    = d.tracks.items.map(t => ({ name: t.name, artist: t.artists[0]?.name, uri: t.uri }));
    if (d.playlists) results.playlists = d.playlists.items.map(pl => ({ name: pl.name, tracks: pl.tracks?.total, uri: pl.uri }));
    if (d.artists)   results.artists   = d.artists.items.map(a => ({ name: a.name, uri: a.uri }));
    return { json: { query: input.query, results } };
  }
  if (action === 'play' && (input.query || input.uri)) {
    let uri = input.uri;
    if (!uri && input.query) {
      const sRes = await fetch(`https://api.spotify.com/v1/search?q=${encodeURIComponent(input.query)}&type=track,playlist&limit=1&market=TH`, { headers });
      const sData = await sRes.json();
      uri = sData.tracks?.items?.[0]?.uri || sData.playlists?.items?.[0]?.uri;
      if (!uri) return { json: { error: `Nothing found for: ${input.query}` } };
    }
    const isContext = uri.includes(':album:') || uri.includes(':playlist:') || uri.includes(':artist:');
    const body = isContext ? { context_uri: uri } : { uris: [uri] };
    await fetch('https://api.spotify.com/v1/me/player/play', { method: 'PUT', headers, body: JSON.stringify(body) });
    return { json: { success: true, message: i18n.success, playing: uri } };
  }
  if (action === 'list_devices') {
    const res = await fetch('https://api.spotify.com/v1/me/player/devices', { headers });
    const d = await res.json();
    return { json: { devices: (d.devices || []).map(dev => ({ id: dev.id, name: dev.name, type: dev.type, is_active: dev.is_active, volume_pct: dev.volume_percent })) } };
  }
  if (action === 'create_playlist') {
    if (!input.name) return { json: { error: i18n.name_required || 'name required' } };
    const meRes = await fetch('https://api.spotify.com/v1/me', { headers });
    const me = await meRes.json();
    const res = await fetch(`https://api.spotify.com/v1/users/${me.id}/playlists`, {
      method: 'POST', headers,
      body: JSON.stringify({ name: input.name, description: input.description || '', public: false })
    });
    const d = await res.json();
    return { json: { success: true, message: i18n.success, playlist_id: d.id, name: d.name, url: d.external_urls?.spotify } };
  }
  return { json: { error: `Unknown action: ${action}. Use: now_playing|play|pause|resume|next|prev|set_volume|set_shuffle|search|list_devices|create_playlist` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n = ctx.i18n || {};
const action = (input.action || 'list_rooms').toLowerCase();
const sonosBase = (creds.sonos_api_url || process.env.SONOS_HTTP_API_URL || '').replace(/\/$/, '');

if (!sonosBase) return { json: { error: `Sonos ${i18n.not_connected}`, help: i18n.configure, note: i18n.sonos_note } };

try {
  const call = async (path) => {
    const res = await fetch(`${sonosBase}${path}`);
    if (!res.ok) throw new Error(`Sonos HTTP ${res.status}: ${path}`);
    try { return await res.json(); } catch { return { ok: true }; }
  };
  if (action === 'list_rooms') {
    const data = await call('/zones');
    const rooms = (data || []).flatMap(z =>
      z.members?.map(m => ({ room: m.roomName, uuid: m.uuid, state: m.state?.playbackState })) || []
    );
    return { json: { rooms, count: rooms.length } };
  }
  if (action === 'pause_all') {
    await call('/pauseAll');
    return { json: { success: true, message: i18n.success, action: 'paused all rooms' } };
  }
  if (action === 'resume_all') {
    await call('/resumeAll');
    return { json: { success: true, message: i18n.success, action: 'resumed all rooms' } };
  }
  const room = input.room;
  if (!room) return { json: { error: i18n.room_required || 'room name required for this action' } };
  const r = encodeURIComponent(room);
  if (action === 'play') {
    await call(`/${r}/play`);
    return { json: { success: true, message: i18n.success, room, action: 'play' } };
  }
  if (action === 'pause') {
    await call(`/${r}/pause`);
    return { json: { success: true, message: i18n.success, room, action: 'pause' } };
  }
  if (action === 'now_playing') {
    const d = await call(`/${r}/state`);
    return { json: { room, ...d } };
  }
  if (action === 'set_volume') {
    const vol = Math.min(100, Math.max(0, parseInt(input.volume || 50)));
    await call(`/${r}/volume/${vol}`);
    return { json: { success: true, message: i18n.success, room, volume: vol } };
  }
  if (action === 'play_spotify') {
    if (!input.spotify_uri) return { json: { error: 'spotify_uri required' } };
    await call(`/${r}/spotify/now/${encodeURIComponent(input.spotify_uri)}`);
    return { json: { success: true, message: i18n.success, room, spotify_uri: input.spotify_uri } };
  }
  return { json: { error: `Unknown action: ${action}. Use: list_rooms|play|pause|set_volume|play_spotify|pause_all|resume_all|now_playing` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}`, note: i18n.sonos_note || 'Is node-sonos-http-api running?' } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n = ctx.i18n || {};
const lang = ctx.lang || 'th';
const action = (input.action || 'get_states').toLowerCase();
const haUrl   = (creds.ha_url || '').replace(/\/$/, '');
const haToken = creds.ha_token || '';

if (!haUrl || !haToken) return { json: { error: `Home Assistant ${i18n.not_connected}`, help: i18n.configure } };
const haHeaders = { 'Authorization': `Bearer ${haToken}`, 'Content-Type': 'application/json' };

const localLang = ['th','en','ja','zh'].includes(lang) ? lang : 'en';

// Ambient mode definitions (multilingual descriptions + HA settings)
const ambientModes = {
  morning: {
    desc: { th: 'เช้า: แสงสว่าง 5000K + เพลง energetic', en: 'Morning: Bright 5000K + energy music', ja: '朝: 明るい5000K + エネルギッシュ音楽', zh: '早晨: 明亮5000K + 活力音乐' },
    lights: { entity_id: 'all', brightness_pct: 80, kelvin: 5000 },
    spotify_query: 'morning energy playlist'
  },
  work: {
    desc: { th: 'ทำงาน: แสง neutral 4000K + lo-fi', en: 'Work: Neutral 4000K + lo-fi music', ja: '作業: ニュートラル4000K + ローファイ', zh: '工作: 中性4000K + lo-fi音乐' },
    lights: { entity_id: 'all', brightness_pct: 100, kelvin: 4000 },
    spotify_query: 'lo-fi hip hop focus'
  },
  relax: {
    desc: { th: 'ผ่อนคลาย: แสงอุ่น 40% + chill', en: 'Relax: Warm 40% + chill music', ja: 'リラックス: 暖かい40% + チル', zh: '放松: 温暖40% + 轻松音乐' },
    lights: { entity_id: 'all', brightness_pct: 40, kelvin: 2700 },
    spotify_query: 'thai chill acoustic'
  },
  sleep: {
    desc: { th: 'นอน: ไฟดับ + เสียงธรรมชาติ', en: 'Sleep: Lights off + nature sounds', ja: '睡眠: 消灯 + 自然の音', zh: '睡眠: 关灯 + 自然声音' },
    lights: { entity_id: 'all', service: 'turn_off' },
    spotify_query: 'sleep sounds rain'
  },
  movie: {
    desc: { th: 'ดูหนัง: แสงริมๆ + ไม่มีเพลง', en: 'Movie: Dim ambient light + no music', ja: '映画: 薄暗い照明 + 音楽なし', zh: '电影: 昏暗灯光 + 无音乐' },
    lights: { entity_id: 'all', brightness_pct: 8, kelvin: 2200 },
    spotify_query: null
  },
  study: {
    desc: { th: 'อ่านหนังสือ: แสงจ้า 6000K + classical', en: 'Study: Bright 6000K + classical music', ja: '勉強: 明るい6000K + クラシック', zh: '学习: 明亮6000K + 古典音乐' },
    lights: { entity_id: 'all', brightness_pct: 100, kelvin: 6000 },
    spotify_query: 'classical concentration'
  }
};

try {
  if (action === 'set_ambient_mode') {
    const mode = (input.mode || 'relax').toLowerCase();
    const preset = ambientModes[mode];
    if (!preset) return { json: { error: `Unknown mode: ${mode}`, available: Object.keys(ambientModes) } };
    const lightSvc = preset.lights.service === 'turn_off' ? 'turn_off' : 'turn_on';
    const lightData = { entity_id: preset.lights.entity_id };
    if (preset.lights.brightness_pct) lightData.brightness_pct = preset.lights.brightness_pct;
    if (preset.lights.kelvin) lightData.color_temp_kelvin = preset.lights.kelvin;
    await fetch(`${haUrl}/api/services/light/${lightSvc}`, { method: 'POST', headers: haHeaders, body: JSON.stringify(lightData) });
    const description = preset.desc[localLang] || preset.desc['en'];
    return { json: { success: true, message: i18n.success, mode, description, spotify_suggestion: preset.spotify_query } };
  }
  if (action === 'get_states') {
    const res = await fetch(`${haUrl}/api/states`, { headers: haHeaders });
    if (!res.ok) throw new Error(`HA API error: ${res.status}`);
    const states = await res.json();
    const relevant = (states || [])
      .filter(s => ['light','switch','climate','sensor','media_player'].some(d => s.entity_id.startsWith(d)))
      .slice(0, 20)
      .map(s => ({ entity_id: s.entity_id, state: s.state, friendly_name: s.attributes?.friendly_name }));
    return { json: { devices: relevant, count: relevant.length } };
  }
  if (action === 'lights_on') {
    const entityId = input.entity_id || 'all';
    await fetch(`${haUrl}/api/services/light/turn_on`, { method: 'POST', headers: haHeaders, body: JSON.stringify({ entity_id: entityId }) });
    return { json: { success: true, message: i18n.success, action: 'lights on', entity_id: entityId } };
  }
  if (action === 'lights_off') {
    const entityId = input.entity_id || 'all';
    await fetch(`${haUrl}/api/services/light/turn_off`, { method: 'POST', headers: haHeaders, body: JSON.stringify({ entity_id: entityId }) });
    return { json: { success: true, message: i18n.success, action: 'lights off', entity_id: entityId } };
  }
  if (action === 'set_lights') {
    const entityId = input.entity_id || 'all';
    const data = { entity_id: entityId };
    if (input.brightness_pct !== undefined) data.brightness_pct = Math.min(100, Math.max(0, parseInt(input.brightness_pct)));
    if (input.kelvin !== undefined) data.color_temp_kelvin = Math.min(6500, Math.max(2700, parseInt(input.kelvin)));
    await fetch(`${haUrl}/api/services/light/turn_on`, { method: 'POST', headers: haHeaders, body: JSON.stringify(data) });
    return { json: { success: true, message: i18n.success, entity_id: entityId, ...data } };
  }
  if (action === 'call_service') {
    const { domain, service, entity_id, service_data } = input;
    if (!domain || !service) return { json: { error: 'domain and service required' } };
    const body = { entity_id, ...(service_data || {}) };
    await fetch(`${haUrl}/api/services/${domain}/${service}`, { method: 'POST', headers: haHeaders, body: JSON.stringify(body) });
    return { json: { success: true, message: i18n.success, called: `${domain}.${service}`, entity_id } };
  }
  return { json: { error: `Unknown action: ${action}. Use: get_states|lights_on|lights_off|set_lights|call_service|set_ambient_mode` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

const input = JSON.parse($input.first().json.query || '{}');
const ctx = $('Load Credentials').first().json;
const creds = ctx.credentials || {};
const i18n = ctx.i18n || {};
const lookupType = (input.lookup_type || 'recent_tracks').toLowerCase();
const lfKey  = creds.lastfm_api_key   || '';
const lfUser = creds.lastfm_username  || '';
const lfSk   = creds.lastfm_session_key || '';
const ytKey  = creds.youtube_api_key  || '';

try {
  // ── YouTube Music Search ─────────────────────────────────────
  if (lookupType === 'youtube_music_search') {
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    if (!ytKey) return { json: { error: `YouTube API key ${i18n.not_connected}`, help: i18n.configure } };
    const res = await fetch(
      `https://www.googleapis.com/youtube/v3/search?part=snippet&q=${encodeURIComponent(input.query + ' official audio')}&type=video&videoCategoryId=10&maxResults=5&key=${ytKey}`
    );
    const data = await res.json();
    if (data.error) return { json: { error: data.error.message } };
    return { json: {
      results: (data.items || []).map(v => ({
        title:   v.snippet.title,
        channel: v.snippet.channelTitle,
        url:     `https://youtube.com/watch?v=${v.id.videoId}`
      })),
      note: i18n.youtube_note
    }};
  }

  // ── All Last.fm methods need API key ─────────────────────────
  if (!lfKey) return { json: { error: `Last.fm API key ${i18n.not_connected}`, help: i18n.configure } };

  // ── Scrobble Track ────────────────────────────────────────────
  if (lookupType === 'scrobble_track') {
    if (!input.artist || !input.track) return { json: { error: 'artist and track required' } };
    if (!lfSk) return { json: { error: 'Last.fm session key not configured (need auth)', help: i18n.configure } };
    // Note: Live HMAC scrobbling requires signing; log locally for now
    return { json: {
      info: `Track logged: ${input.artist} - ${input.track}`,
      note: 'Live Last.fm scrobbling requires HMAC auth. Track logged for reference only.',
      artist: input.artist, track: input.track, scrobbled: false
    }};
  }

  // ── Recent Tracks ─────────────────────────────────────────────
  if (lookupType === 'recent_tracks') {
    if (!lfUser) return { json: { error: 'lastfm_username not configured', help: i18n.configure } };
    const res = await fetch(
      `https://ws.audioscrobbler.com/2.0/?method=user.getrecenttracks&user=${lfUser}&api_key=${lfKey}&limit=10&format=json`
    );
    const data = await res.json();
    if (data.error) return { json: { error: data.message } };
    const tracks = (data.recenttracks?.track || []).map(t => ({
      artist: t.artist?.['#text'], track: t.name, album: t.album?.['#text'],
      now_playing: t['@attr']?.nowplaying === 'true'
    }));
    return { json: { tracks, count: tracks.length } };
  }

  // ── Top Tracks ────────────────────────────────────────────────
  if (lookupType === 'top_tracks') {
    if (!lfUser) return { json: { error: 'lastfm_username not configured', help: i18n.configure } };
    const period = input.period || '1month'; // 7day|1month|3month|6month|12month|overall
    const res = await fetch(
      `https://ws.audioscrobbler.com/2.0/?method=user.gettoptracks&user=${lfUser}&api_key=${lfKey}&period=${period}&limit=10&format=json`
    );
    const data = await res.json();
    if (data.error) return { json: { error: data.message } };
    const tracks = (data.toptracks?.track || []).map(t => ({
      rank: t['@attr']?.rank, artist: t.artist?.name, track: t.name, playcount: t.playcount
    }));
    return { json: { tracks, period, count: tracks.length } };
  }

  // ── Artist Info ───────────────────────────────────────────────
  if (lookupType === 'artist_info') {
    if (!input.query) return { json: { error: i18n.query_required || 'query required' } };
    const res = await fetch(
      `https://ws.audioscrobbler.com/2.0/?method=artist.getinfo&artist=${encodeURIComponent(input.query)}&api_key=${lfKey}&format=json`
    );
    const data = await res.json();
    if (data.error) return { json: { error: data.message } };
    const a = data.artist;
    return { json: {
      name: a.name,
      bio: a.bio?.summary?.replace(/<[^>]+>/g, '').slice(0, 500),
      tags: (a.tags?.tag || []).map(t => t.name),
      plays: a.stats?.playcount,
      similar: (a.similar?.artist || []).slice(0, 5).map(s => s.name)
    }};
  }

  return { json: { error: `Unknown lookup_type: ${lookupType}. Use: scrobble_track | recent_tracks | top_tracks | youtube_music_search | artist_info` } };
} catch(e) {
  return { json: { error: `${i18n.error||'Error'}: ${e.message}` } };
}

// Format Output v5 — normalized for WF2 synthesis
// Dispatch Gate reads: data?.message || data?.response || data?.output || data?.agentOutput || data?.text
// n8n LangChain agent returns output in: output field (primary), then agentOutput, then text
const raw  = $input.first().json;
const out  = raw.output || raw.agentOutput || raw.text || raw.message || 'ดำเนินการแล้วครับ';
const prev = $('Extract Payload').item.json;
const result = {
  ...prev,
  message:       out,
  response:      out,
  output:        out,
  agentOutput:   out,
  agentCategory: 'home-mate',
  processedAt:   new Date().toISOString(),
  _llm_tier:     raw._llm_tier || 'langchain'
};
return { json: result };
